<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import{ElMessage,ElMessageBox}from'element-plus'
import{useAuthStore}from'../../stores/auth'
import{getRecords}from'../../services/records'
import{createExamination,downloadMedicalFile,getExaminations,publishReport,saveReport,startExamination,uploadMedicalFile}from'../../services/examinations'
import type{ExaminationOrder,MedicalRecord}from'../../types/medical'

const auth=useAuthStore(),role=computed(()=>auth.user!.role),rows=ref<ExaminationOrder[]>([]),total=ref(0),loading=ref(false),createOpen=ref(false),reportOpen=ref(false),detailOpen=ref(false),saving=ref(false),records=ref<MedicalRecord[]>([]),current=ref<ExaminationOrder|null>(null),selectedFile=ref<File|null>(null)
const form=reactive({record_id:0,type:'lab',clinical_question:''}),report=reactive({findings:'',conclusion:''})
const types=[['blood','血液检查'],['lab','常规检验'],['xray','X-Ray'],['ct','CT'],['mri','MRI'],['other','其他检查']]
const tagType:Record<string,''|'success'|'warning'|'info'|'danger'>={requested:'warning',in_progress:'',completed:'warning',published:'success',cancelled:'info'}
async function load(){loading.value=true;try{const data=await getExaminations();rows.value=data.results;total.value=data.count}catch{rows.value=[];total.value=0}finally{loading.value=false}}
async function openCreate(){Object.assign(form,{record_id:0,type:'lab',clinical_question:''});createOpen.value=true;try{records.value=(await getRecords({status:'confirmed'})).results}catch{records.value=[]}}
async function submit(){if(!form.record_id||!form.clinical_question.trim()){ElMessage.warning('请选择病历并填写检查目的');return}saving.value=true;try{await createExamination(form);ElMessage.success('检查申请已创建');createOpen.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'创建失败')}finally{saving.value=false}}
async function start(row:ExaminationOrder){try{await startExamination(row.id);ElMessage.success('检查已开始处理');await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'无法开始检查')}}
function openReport(row:ExaminationOrder){current.value=row;report.findings=row.report?.findings||'';report.conclusion=row.report?.conclusion||'';selectedFile.value=null;reportOpen.value=true}
function chooseFile(event:Event){const input=event.target as HTMLInputElement;selectedFile.value=input.files?.[0]||null}
async function submitReport(){if(!current.value||!report.findings.trim()||!report.conclusion.trim()){ElMessage.warning('检查所见和结论不能为空');return}saving.value=true;try{await saveReport(current.value.id,report);if(selectedFile.value)await uploadMedicalFile(current.value.id,selectedFile.value);ElMessage.success('检查报告已保存');reportOpen.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'报告保存失败')}finally{saving.value=false}}
async function publish(row:ExaminationOrder){try{await ElMessageBox.confirm('发布后患者将可以查看报告和附件。','发布检查报告',{type:'warning'});await publishReport(row.id);ElMessage.success('报告已发布');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'发布失败')}}
async function download(id:number,name:string){try{await downloadMedicalFile(id,name)}catch{ElMessage.error('附件下载失败或无权访问')}}
function view(row:ExaminationOrder){current.value=row;detailOpen.value=true}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">MEDICAL EXAMINATION</p><h1>{{role==='doctor'?'医学检查':role==='patient'?'检查报告':'检查管理'}}</h1><p>{{role==='doctor'?'创建检查申请，录入检查结果并向患者发布报告':role==='patient'?'查看已经发布的个人检查结果和附件':'审核、录入并发布检查报告'}}</p></div><el-button v-if="role==='doctor'" type="primary" @click="openCreate">＋ 申请检查</el-button></div><el-card class="table-card"><el-table v-loading="loading" :data="rows" empty-text="暂无检查记录"><el-table-column prop="order_no" label="申请单号" min-width="150"/><el-table-column v-if="role!=='patient'" prop="patient_name" label="患者" min-width="110"/><el-table-column v-else prop="doctor_name" label="医师" min-width="110"/><el-table-column prop="type_display" label="检查类型" width="110"/><el-table-column prop="clinical_question" label="检查目的" min-width="220" show-overflow-tooltip/><el-table-column prop="created_at" label="申请时间" min-width="160"/><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="tagType[row.status]||'info'">{{row.status_display}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="260" fixed="right"><template #default="{row}"><el-button link type="primary" @click="view(row)">查看</el-button><template v-if="role==='admin'||role==='doctor'"><el-button v-if="row.status==='requested'" link @click="start(row)">开始检查</el-button><el-button v-if="row.status==='requested'||row.status==='in_progress'||row.status==='completed'" link @click="openReport(row)">{{row.report?'编辑报告':'录入报告'}}</el-button><el-button v-if="row.status==='completed'" link type="success" @click="publish(row)">发布</el-button></template></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span></div></el-card><el-dialog v-model="createOpen" title="创建检查申请" width="min(620px,94vw)"><el-form label-position="top"><el-form-item label="关联已确认病历" required><el-select v-model="form.record_id" filterable style="width:100%"><el-option v-for="item in records" :key="item.id" :label="`${item.patient_name} · ${item.record_no} · ${item.diagnosis}`" :value="item.id"/></el-select></el-form-item><el-form-item label="检查类型" required><el-select v-model="form.type" style="width:100%"><el-option v-for="item in types" :key="item[0]" :label="item[1]" :value="item[0]"/></el-select></el-form-item><el-form-item label="检查目的与临床问题" required><el-input v-model="form.clinical_question" type="textarea" :rows="4" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="createOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交申请</el-button></template></el-dialog><el-dialog v-model="reportOpen" title="录入检查报告" width="min(680px,94vw)"><el-form label-position="top"><el-form-item label="检查所见" required><el-input v-model="report.findings" type="textarea" :rows="5"/></el-form-item><el-form-item label="检查结论" required><el-input v-model="report.conclusion" type="textarea" :rows="4"/></el-form-item><el-form-item label="报告或影像附件"><input class="file-input" type="file" accept=".jpg,.jpeg,.png,.pdf,.dcm,.nii,.gz" @change="chooseFile"><small>支持 JPG、PNG、PDF、DICOM、NIfTI，单个文件不超过 10MB</small></el-form-item></el-form><template #footer><el-button @click="reportOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitReport">保存报告</el-button></template></el-dialog><el-drawer v-model="detailOpen" title="检查详情" size="min(620px,94vw)"><div v-if="current" class="record-detail"><div><span>申请单号</span><b>{{current.order_no}}</b></div><div><span>检查类型</span><b>{{current.type_display}}</b></div><div><span>检查目的</span><p>{{current.clinical_question}}</p></div><template v-if="current.report"><div><span>检查所见</span><p>{{current.report.findings}}</p></div><div><span>检查结论</span><p>{{current.report.conclusion}}</p></div></template><section v-if="current.files?.length"><h3>检查附件</h3><button v-for="file in current.files" :key="file.id" class="file-link" @click="download(file.id,file.original_name)">{{file.original_name}} <span>{{(file.size/1024).toFixed(1)}} KB</span></button></section><el-empty v-if="!current.report" description="检查报告尚未录入或发布"/></div></el-drawer></section></template>
